INSERT INTO `cyberrisicos` (`id`, `titel`, `omschrijving`, `categorie`, `prioriteit`, `status`, `locatie`, `gemeld_door`, `eigenaar_id`, `datum_geconstateerd`, `datum_gemeld`, `oplossingsadvies`, `bewijs_notities`, `is_gevoelig`, `aangemaakt_door_id`, `created_at`, `updated_at`, `deleted_at`, `afdeling_id`) VALUES
(1, 'Wachtwoord beheer', 'Er zijn gebruikers met wachtwoorden lokaal in een onbeveiligd document opgeslagen', 'onveilige_opslag', 'middel', 'nieuw', NULL, 'Timo', 1, '2026-06-30', '2026-06-30', 'Password manager uitrollen voor het hele bedrijf', 'Jaap op bureaublad\r\nGerard QR/barcode achtergrond scherm\r\nQR code bundels\r\nLabels blaadje ergens op een order achtig iets', 1, 1, '2026-07-02 07:57:32', '2026-07-02 07:59:19', NULL, NULL),
(2, 'Deur opening', 'De deur staat vaak open en onbeheerd met een kabel.\r\nNaast brand veiligheid kan zo iedereen het pand binnen\r\n\r\nToegankelijkheid is gewenst door eind gebruiker', 'fysieke_toegang', 'laag', 'nieuw', 'Repair', 'Timo', NULL, '2026-06-29', NULL, 'Kabel tussen deur weg, binnen met een druppel', NULL, 0, 1, '2026-07-02 08:01:30', '2026-07-02 08:01:30', NULL, NULL),
(3, 'Outdated / niet werkende anti virus', 'Sentinel One is niet overal geinstalleerd of up to date', 'device_exposure', 'middel', 'nieuw', 'Kantoor', 'ACA IT', NULL, NULL, NULL, 'Updates uitvoeren vanuit ninjaone', NULL, 0, 1, '2026-07-06 07:16:14', '2026-07-06 07:16:14', NULL, NULL),
(4, 'Stickynote wachtwoord kloksysteem', 'Bij het herstarten van het systeem had ik een wachtwoord nodig.\r\nAlleen niemand was daar. Fysiek naar de balie gelopen en zag daar op de laptop het wachtwoord liggen wat werkt.', 'fysieke_toegang', 'middel', 'nieuw', 'Balie', 'Timo', 1, '2026-07-06', NULL, NULL, NULL, 1, 1, '2026-07-06 14:02:51', '2026-07-06 14:02:51', NULL, NULL),
(5, 'Medewerker oude login nog beschikbaar', 'wrui\r\n\r\nWillem Ruisch', 'device_exposure', 'middel', 'nieuw', NULL, 'Timo', 1, '2026-07-06', NULL, 'Account lijst opschonen', 'In NinjaOne niet actieve devices', 0, 1, '2026-07-06 14:07:41', '2026-07-06 14:07:41', NULL, NULL),
(6, 'Laptop Rinaldo geen NinjaOne', 'De laptop van Rinaldo bevat geen NinjaOne\r\n\r\nOverleggen wat mogelijk is', 'device_exposure', 'middel', 'nieuw', NULL, NULL, NULL, NULL, '2026-07-13', NULL, NULL, 0, 1, '2026-07-13 13:08:34', '2026-07-20 08:31:02', '2026-07-20 08:31:02', NULL),
(7, 'QR code wachtwoord', 'PC labelsveldhoven voor het inruilen van gereedschap, bij de repair bay heeft een QR code op het scherm zitten', 'device_exposure', 'middel', 'nieuw', 'Repairbay', NULL, NULL, NULL, '2026-07-20', NULL, NULL, 1, 1, '2026-07-20 08:27:10', '2026-07-20 08:27:10', NULL, NULL),
(8, 'Wachtwoord labels', 'Wachtwoord zit op een mapje bij de rechter computer', 'device_exposure', 'middel', 'nieuw', 'Labels', NULL, NULL, NULL, '2026-07-20', NULL, NULL, 1, 1, '2026-07-20 08:27:53', '2026-07-20 08:27:53', NULL, NULL);
