INSERT INTO `kennisbank_artikelen` (`id`, `titel`, `categorie`, `inhoud`, `auteur_id`, `created_at`, `updated_at`, `deleted_at`, `quick_action_type`, `quick_action_omschrijving`, `quick_action_script`, `subcategorie`, `samenvatting`, `tags`) VALUES
(1, 'Minix wifi driver', 'Instructie', '1. Go to \'Device Manager\' by right-click \'This PC\' icon on the desktop, and choose \'Manage\' option. (See attach picture step1.png)\r\n\r\n2. Right-click the driver with a yellow icon, and click \'update driver\' option. yellow icon.webp (See step1.png)\r\n\r\n3. In the prompted window (step2.png), click \'Browse my computer for driver software\'.\r\n\r\n4. Click \'Browse\' to load the driver. Just pick the folder where the driver is located. (See step3.png)\r\nIf any user does not know which driver folder to load, just pick the folder that holds all the drivers, so that you won\'t pick the wrong one.\r\n\r\nPlease note, the \"802.11 ac WDI SDIO\" device is the Wi-Fi device, and when finished manually installing the Wi-Fi driver, you\'ll have to move 4345r6nvram.txt to the folder C:\\Windows\\System32\\drivers\\, and restart the box to make the driver take effect.\r\n\r\nBluetooth driver and Wi-Fi driver are both in the \"Z83-4 WiFi driver\" folder.\r\n\r\n\r\nThe drivers are available from the link below:\r\n\r\nAll drivers (301MB): https://files.theminixforum.com/shared/drivers/Z83-4_CherryTrail-T3-64bit_drivers.zip\r\n\r\nA driver that fixes that the SD card cannot be seen: https://files.theminixforum.com/shared/drivers/Z83-4-Driver-Fix_SD_card_cannot_be_seen.zip\r\n\r\nhttps://theminixforum.com/index.php?threads/neo-z83-4-manually-install-the-driver.31/', 1, '2026-07-02 10:57:26', '2026-07-02 10:57:49', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(2, 'Ceetis TE installeren', 'Instructie', 'Officiele installer gebruiken\r\nSchijven configureren\r\nUserdata script uitvoeren\r\nInloggen\r\nTest station zoeken (naam & IP)\r\nProject folder selecteren\r\nTemplate selecteren', 1, '2026-07-02 11:01:30', '2026-07-02 11:01:30', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(3, 'Printer via powershell toevoegen', 'Script', 'Het draadloos toevoegen van printers binnen het domein\r\nrundll32 printui.dll,PrintUIEntry /y /n \"\\\\fs01-vhe\\HP OfficeJet 7740 BG-Testen Proto\"\r\n\r\nOf gebruik \r\nhttps://bergthaler.dev/printers', 1, '2026-07-02 11:02:49', '2026-07-02 11:02:49', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(4, 'Lokaal admin DMN-VHE account rechten toekennen', 'Script', 'net localgroup administrators \"dmn-vhe\\timo.bergthaler\" /add', 1, '2026-07-02 11:04:10', '2026-07-02 11:04:10', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(5, 'Nieuw lokaal admin account maken', 'Script', '$Password = Read-Host -AsSecureString -Prompt \"Voer wachtwoord voor admin in\" New-LocalUser -Name \"admin\" -Password $Password -Description \"Lokale administrator\" Add-LocalGroupMember -Group \"Administrators\" -Member \"admin\"\r\n\r\n\r\n\r\n$Password = Read-Host -AsSecureString -Prompt \"Voer wachtwoord voor gebruiker in\"\r\n\r\nNew-LocalUser -Name \"gebruiker\" `\r\n    -Password $Password `\r\n    -Description \"Normale lokale gebruiker\"', 1, '2026-07-02 11:04:37', '2026-07-20 13:40:41', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(6, 'Altec driver link', 'URL', 'https://altec.nl/en/downloads/?srsltid=AfmBOoorS3CjJJnrXBbIPUqiA_9PRRCMg7AkCh4pY5RfrhdSvT2h7KcR', 1, '2026-07-02 11:05:01', '2026-07-02 11:05:01', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(7, 'Domein toevoegen via powershell', 'Script', 'Add-Computer -DomainName corp.vhe.nl -Credential corp.vhe.nl\\admintimo -Restart', 1, '2026-07-02 11:05:35', '2026-07-02 11:05:35', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(8, 'Hernoemen computer', 'Script', 'Rename-Computer -NewName \"DESKTOP-JANN\"', 1, '2026-07-02 11:06:05', '2026-07-02 11:06:05', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(9, 'Sharepoint global template', 'Instructie', 'Iedereen krijgt hiermee de templates te zien\r\nhttps://www.youtube.com/watch?v=qkLSwOurOOc\r\n\r\nVoor het verbinden naar een site moet je deze powershell gebruiken	\r\nhttps://www.youtube.com/watch?v=6tdrzbB0bZA', 1, '2026-07-02 11:07:48', '2026-07-02 11:07:48', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(10, 'Ophalen alle printers PC', 'Script', 'Get-Printer -ComputerName fs01-vhe', 1, '2026-07-02 11:08:07', '2026-07-02 11:08:07', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(11, 'Tijdzone instellen', 'Script', '\"# Tijdzone instellen (Maleisië = UTC+8, valt onder Windows-ID \"\"Singapore Standard Time\"\")\r\nSet-TimeZone -Id \"\"Singapore Standard Time\"\"\r\n\r\n# Controleren\r\nGet-TimeZone\r\n\r\n# Tijdsynchronisatie forceren\r\nStop-Service w32time\r\nStart-Service w32time\r\nw32tm /resync /force\r\n\r\n# Status controleren\r\nw32tm /query /status\"', 1, '2026-07-02 11:08:25', '2026-07-02 11:08:25', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(12, 'OSDCloud Installeren', 'Instructie', 'Windows ADK: https://learn.microsoft.com/en-us/windows-hardware/get-started/adk-install\r\nWindows PE: https://learn.microsoft.com/nl-nl/windows-hardware/manufacture/desktop/download-winpe--windows-pe?view=windows-11\r\n\r\nhttps://youtu.be/B1GMRgV_4i4?si=l4DSgzuq6XsPXSmq', 1, '2026-07-02 12:02:16', '2026-07-02 12:03:29', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(13, 'Fout weergeven op afstand', 'Script', '$wshell = New-Object -ComObject Wscript.Shell\r\n$wshell.Popup(\"Er is een fout opgetreden bij het uitvoeren van deze actie.`n`nFoutcode: 0x8007000E\", 0, \"Foutmelding\", 16)\r\n\r\n---------------------------------------\r\n\r\nScript mail \\/\r\n\r\n---------------------------------------\r\nAdd-Type -AssemblyName System.Windows.Forms\r\nAdd-Type -AssemblyName System.Drawing\r\n\r\n$form = New-Object System.Windows.Forms.Form\r\n$form.Text = \"Foutmelding\"\r\n$form.Size = New-Object System.Drawing.Size(400,200)\r\n$form.StartPosition = \"CenterScreen\"\r\n$form.Topmost = $true\r\n$form.FormBorderStyle = \"FixedDialog\"\r\n$form.MaximizeBox = $false\r\n$form.MinimizeBox = $false\r\n\r\n$label = New-Object System.Windows.Forms.Label\r\n$label.Text = \"Er heeft een fout opgetreden met een software update.`n`nGelieve een mail te sturen naar IT@vhe.nl\"\r\n$label.AutoSize = $false\r\n$label.Size = New-Object System.Drawing.Size(360,80)\r\n$label.Location = New-Object System.Drawing.Point(15,15)\r\n$form.Controls.Add($label)\r\n\r\n$button = New-Object System.Windows.Forms.Button\r\n$button.Text = \"Verstuur mail naar IT\"\r\n$button.Size = New-Object System.Drawing.Size(160,30)\r\n$button.Location = New-Object System.Drawing.Point(115,110)\r\n$button.Add_Click({\r\n    Start-Process \"mailto:IT@vhe.nl?subject=Foutmelding%20software%20update\"\r\n    $form.Close()\r\n})\r\n$form.Controls.Add($button)\r\n$form.AcceptButton = $button\r\n\r\n[void]$form.ShowDialog()', 1, '2026-07-02 14:06:25', '2026-07-02 14:42:08', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(14, 'Python installeren via powershell', 'Script', '# Install-Python.ps1\r\n$ErrorActionPreference = \"Stop\"\r\n\r\n$pythonVersion = \"3.12.6\"  # pas aan naar gewenste versie\r\n$installerUrl  = \"https://www.python.org/ftp/python/$pythonVersion/python-$pythonVersion-amd64.exe\"\r\n$installerPath = \"$env:TEMP\\python-installer.exe\"\r\n\r\nWrite-Output \"Downloading Python $pythonVersion...\"\r\nInvoke-WebRequest -Uri $installerUrl -OutFile $installerPath -UseBasicParsing\r\n\r\nWrite-Output \"Installing Python silently...\"\r\n$arguments = @(\r\n    \"/quiet\"\r\n    \"InstallAllUsers=1\"\r\n    \"PrependPath=1\"\r\n    \"Include_test=0\"\r\n    \"Include_launcher=1\"\r\n)\r\n\r\nStart-Process -FilePath $installerPath -ArgumentList $arguments -Wait -NoNewWindow\r\n\r\nWrite-Output \"Cleaning up...\"\r\nRemove-Item $installerPath -Force\r\n\r\nWrite-Output \"Python $pythonVersion installation complete.\"', 1, '2026-07-06 07:09:12', '2026-07-06 07:09:12', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(15, 'exact portaal connection', 'handleiding', 'server = \\\\db03\r\ncompany 400\r\n\r\nDaarna bij company op een pijltje omlaag klikken\r\nHier krijg je 2 opties\r\nKies dan optie 400 - VHE Industrial automation B.V.', 1, '2026-07-09 07:17:41', '2026-07-09 07:25:59', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(16, 'Wachtwoord reset', 'Account beheer', 'Alleen via Frank\r\n\r\nAls ik dit doe dan werkt het niet. De entra en AD lopen niet synchroon', 1, '2026-07-13 06:26:23', '2026-07-13 13:14:44', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(17, 'windows update uitzetten (10 jaar)', 'Script', '$action = New-ScheduledTaskAction -Execute \"powershell.exe\" `\r\n    -Argument \"-NoProfile -WindowStyle Hidden -Command `\"Stop-Service -Name wuauserv -Force; Set-Service -Name wuauserv -StartupType Disabled`\"\"\r\n\r\n$trigger = New-ScheduledTaskTrigger -Once -At (Get-Date) `\r\n    -RepetitionInterval (New-TimeSpan -Hours 6) `\r\n    -RepetitionDuration (New-TimeSpan -Days 3650)\r\n\r\n$principal = New-ScheduledTaskPrincipal -UserId \"SYSTEM\" -LogonType ServiceAccount -RunLevel Highest\r\n\r\nRegister-ScheduledTask -TaskName \"Disable-WindowsUpdate\" -Action $action -Trigger $trigger -Principal $principal -Description \"Forceert wuauserv terug naar Disabled elke 6 uur\"', 1, '2026-07-13 07:47:59', '2026-07-13 07:47:59', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(18, 'Brother scanner login', 'Scanner', 'Dit is hoe je inlogd\r\n\r\n> netwerk IP intikken', 1, '2026-07-23 08:35:31', '2026-07-23 08:35:31', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
