INSERT INTO `paginabezoeken` (`id`, `user_id`, `ip_adres`, `methode`, `url`, `user_agent`, `created_at`, `parameters`) VALUES
(3493, 1, '31.160.50.218', 'POST', '/verbeterpunten/19', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/150.0.0.0 Safari/537.36', '2026-07-14 07:30:02', '{\"titel\":\"Update intranet\",\"afdeling_id\":\"\",\"omschrijving\":\"Een aantal kleine verbeterpunten:\\r\\n\\r\\nLogging:\\r\\n- Verdachte login pogingen mailen\\r\\n- Filteren op niet ingelogd naast de users\\r\\n- Post data in popup weergeven in plaats van veel plek op neemt\\r\\n- logging ouder dan X dagen verwijderen\\r\\n\\r\\nUitgifte:\\r\\n- Toestemming manager vinkje\\r\\n\\r\\nCRM\\r\\n- Hirarchie keyusers\\/ stamboom VHE\\r\\n- Nieuwe extentie \\\"urenstaat\\\" bij CRM\\r\\nTijd schrijven hoe laat, op welke locatie (locaties toevoegen via aparte extensie wat persoongebonden of algemeen zijn, zodat als ik een klant of locatie toevoeg niet iedereen of selectief aantal, of hele bedrijf ziet, zoals \\\"kantoor\\\" iedereen en thuis alleen ik, maar klant raith bijvoorbeeld 3 mensen dit zien\\r\\nOnderstaand powershell commando werkt\\r\\n\\r\\n$headers = @{\\r\\n    \\\"x-anwb-caller-id\\\" = \\\"routing\\/traffic-info-web\\\"\\r\\n}\\r\\n\\r\\n$response = Invoke-RestMethod -Uri \\\"https:\\/\\/api.anwb.nl\\/routing\\/route\\/v1\\/route\\/car?locations=51.193943%2C6.001977%3A51.454764%2C5.389512&tollInfo=true&traffic=true&routeType=fastest&includeAlternatives=true\\\" -Headers $headers\\r\\n\\r\\n$response.value | ForEach-Object {\\r\\n    [PSCustomObject]@{\\r\\n        RouteId     = $_.id\\r\\n        AfstandKm   = [math]::Round($_.summary.distanceInMeters \\/ 1000, 1)\\r\\n        DuurMinuten = [math]::Round($_.summary.durationInSeconds \\/ 60, 0)\\r\\n        Wegen       = $_.summary.roadNumbers -join \\\", \\\"\\r\\n        Tol         = $_.summary.tollRoads\\r\\n    }\\r\\n} | Format-Table -AutoSize\\r\\n\\r\\n\\r\\nAlleen zelf coordinaten ophalen op basis van een adres een api voor vinden\\r\\nVoor nu handmatig invullen naast adres\\r\\n\\r\\nTicket\\r\\n- Omschrijving uitklapbaar maken in plaats van dat je alles ziet\\r\\n- Markeren als Cyber risico om hem aan de grafiek te kunnen toevoegen\\r\\n- Tijd logging (5min, 10min, 15min, 30min, 45 min, 60min)\\r\\n- Bij opmerking titel mee kunnen geven\\r\\n- Een caterogie aanpassen, of zoekend selecteren. \\r\\nDus als ik bij de kennisbank hetzelfde kan doen zou top zijn, als ik 2 seconden niet getypt heb met AJAX ophalen\\r\\n\\r\\nSchijfgebruik \\r\\n- Device kunnen koppelen aan medewerker\\r\\n\\r\\n\\r\\nVerbeterpunten & tickets gelijk trekken qua functionaliteit\",\"status\":\"nieuw\"}'),
