INSERT INTO `reflecties` (`id`, `titel`, `periode`, `inhoud`, `gebruiker_id`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, 'Onnodig ACA gemaild', 'Week 28', 'Deze week, nadat frank terug is gekomen van vakantie heb ik ACA gemaild voor 2 account. dit kunnen we namelijk zelf.\r\n\r\nHier was ik beetje te snel in handelen en had eerst Frank moeten vragen om de kosten te besparen.', 1, '2026-07-09 07:15:49', '2026-07-09 07:15:49', NULL),
(2, 'Alternatief programma NiceLabel', 'Week 27', 'Deze week heb ik een alternatieve driver gevonden zodat we niet verplicht zijn om voor elke printer een licentie actief te houden.\r\n\r\nDit is kosten besparend', 1, '2026-07-09 07:16:39', '2026-07-09 07:16:39', NULL),
(3, 'Niet alles willen regelen', '04/08/2026', 'Zojuist een probleem van Rinaldo.\r\n\r\nEr is niets geregeld en er kan 1 medewerker niet werken\r\n\r\nIk ging al meteen het een en ander regelen maar dat is niet mijn taak\r\nwou meteen al gaan organiseren dat er tafels bij komen ect met ilja besproken. Maar goed\r\nFrank hield me terug dat ik niet de shit van andere ga oplossen', 1, '2026-08-04 07:40:37', '2026-08-04 07:40:37', NULL),
(4, 'Spoed overleggen & geen spoed mailen', '06-08-2026', 'vandaag de opmerking gekregen niet iets te mailen en aan te kondigen dat ik dat gemaild heb.', 1, '2026-08-06 14:54:46', '2026-08-06 14:54:46', NULL);
