INSERT INTO `verbeterpunten` (`id`, `titel`, `omschrijving`, `afdeling_id`, `ingediend_door_id`, `status`, `created_at`, `updated_at`, `deleted_at`, `categorie`) VALUES
(1, 'Verbeterpunten portaal', 'TODO:\r\n\r\nHerrinering feature mail\r\n\r\n\r\n\r\nDit zijn dingen waar ik tegen aan ben gelopen met mijn portaal\r\n\r\n- geen opmerkingen kunnen maken bij verbeter voorstellen\r\n\r\nBij tickets:\r\n- tickets bij status en opmerking plaatsen verdwijnt de opmerking bij statuswissel, net zoals wat bij TVM gebeurt.\r\n- Gesloten / opgelost naar afgehandeld combineren\r\n- Export huidige weergave\r\n- Filter toevoegen alle statussen \r\n- Filter aanpassen naar (actieve statussen)\r\n- Opmerking veld boven de opmerkingen zetten\r\n\r\nBij agenda:\r\nSlepen werkt niet lekker in de weergaven, hij slaat niets op\r\n\r\nBij Printer:\r\nsnelkoppeling commando werkt niet bij grote tabel\r\n\r\nBij database:\r\nUTC +1 tijden opslaan\r\n\r\n\r\n3 verbeterpunten (dingen die achterblijven t.o.v. wat je zou verwachten):\r\n\r\nGeen CSRF-bescherming — alle 8+ POST-formulieren (verwijderen, status wijzigen, etc.) hebben geen token; een aanvaller kan met een gemanipuleerde link/pagina destructieve acties laten uitvoeren als een ingelogde gebruiker.\r\nFiltering/sortering/paginering draait volledig in PHP — TicketModel::allWithRelations() (en analoge methodes in andere modules) haalt altijd de héle tabel op, en TableQuery filtert/sorteert/pagineert daarna in-memory. Werkt prima bij 80 tickets, maar schaalt niet naar duizenden.\r\nGeen geautomatiseerde tests — geen composer.json/PHPUnit in de repo. De status-filter bug die we net vonden (55 van de 80 tickets stonden nog op oude statuswaarden) was pas zichtbaar door handmatig de data te dumpen; met tests op TableQuery/applyDefaultFilters was dit eerder opgevallen.\r\n3 features die ik zou verwachten (typisch voor een ticketsysteem, nu ontbrekend):\r\n\r\nE-mail/notificaties — er is nergens een mail()/SMTP-integratie; behandelaars/opdrachtgevers krijgen geen bericht bij een nieuw ticket of statuswijziging.\r\nBijlagen bij tickets — geen upload-mogelijkheid voor screenshots/documenten bij een ticket (alleen bulk-Excel-import bestaat, geen file-attachment per record).\r\nVolledig activiteitenlog per veld — ticket_logs registreert alleen statuswijzigingen + opmerkingen, niet wie bijvoorbeeld prioriteit, behandelaar of deadline heeft aangepast.\r\n3 uitbreidingen die ik zou verwachten (grotere structurele stappen):\r\n\r\nRijniveau-rechten — de rechtenmatrix (RechtenModel) is nu puur module-breed (lezen/schrijven/verwijderen per module); geen \"alleen eigen afdeling zien\"-scoping, wat bij meerdere afdelingen al snel gewenst is.\r\nKoppeling tussen modules — Verbeterpunten, CyberRisico\'s, Voorraad/Uitgifte en Tickets staan volledig los van elkaar; een Verbeterpunt omzetten naar een Ticket, of een Uitgifte koppelen aan een Ticket, zou logisch zijn maar bestaat niet.\r\nAPI/integratielaag — alles is server-rendered HTML zonder JSON-endpoints; voor koppeling met bijv. een mobiele app of externe monitoring zou een API-laag nodig zijn.', NULL, 1, 'uitgevoerd', '2026-07-02 06:40:09', '2026-07-09 09:22:36', NULL, 'Algemeen'),
(2, 'Gebruikers komen met niet IT vragen naar ons toe', 'Frank is hier beetje moe mee', 9, 1, 'nieuw', '2026-07-02 07:40:03', '2026-07-02 07:40:03', NULL, 'Algemeen'),
(3, 'Kabelmanagement bureau\'s', 'Alle stekkerdozen zitten vol en door elkaar gelust', 9, 1, 'nieuw', '2026-07-02 09:21:01', '2026-07-02 09:21:01', NULL, 'Algemeen'),
(4, 'Vaste laptops vervangen met PC', 'Aantal laptops zijn voor de vast, worden niet verplaatst en zijn geen flex plekken.\r\n\r\nMogelijk vervangen met vaste computers', NULL, 1, 'nieuw', '2026-07-02 09:21:40', '2026-07-02 09:21:40', NULL, 'Algemeen'),
(5, 'Inventarisatie serverroom', 'Frank navragen', NULL, 1, 'uitgevoerd', '2026-07-02 09:24:27', '2026-07-07 08:52:09', NULL, 'Algemeen'),
(6, 'Documenteren waar switches staan, welke switches er staan', 'Het is vrijwel een grijs gebied waar switches staan, welke functie deze hebben en wat er daadwerkelijk nodig is.\r\n risico beperking.', NULL, 1, 'nieuw', '2026-07-02 09:26:13', '2026-07-02 09:28:00', NULL, 'Algemeen'),
(7, 'Documentatie printers', 'Ik wil weten waar alle printers staan voor risico beperking en cyber veiligheid', NULL, 1, 'goedgekeurd', '2026-07-02 09:27:50', '2026-07-07 08:52:52', NULL, 'Algemeen'),
(8, 'Licentie mailbox opschonen', 'Mailbox vol met rommel', 9, 1, 'in_overweging', '2026-07-02 09:53:32', '2026-07-07 08:52:03', NULL, 'Algemeen'),
(9, 'Dashboard bouwen voor tv schermen (mirroring)', 'Website maken die documenten op een hoofd pc host naar andere devices via web interface op lokaal netwerk zonder extra hosting\r\n\r\nLokaal in te stellen waarbij hij 2 get requests stuurt\r\n\r\n1 naar de hoofd pc\r\n1 naar een andere backend/api endpoint', 14, 1, 'nieuw', '2026-07-02 11:13:47', '2026-07-02 11:15:25', NULL, 'Algemeen'),
(10, 'Management', '- Programma python bij finance\r\n- Exact\r\n- Ceetis\r\n- RAD Utils\r\n- Twincat\r\n- Onbeheerde database voor labels ASML\r\n\r\nLicentie beheer, Niets gedocumenteerd voor ICT, Geen inhoudelijke ondersteuning.\r\nIs vroeger benoemd maar niets mee gedaan. Wij als ICT nemen taken en ondersteuning over bij absentie van key users die hier vanaf weten', 9, 1, 'nieuw', '2026-07-06 07:01:14', '2026-07-07 08:51:48', NULL, 'Algemeen'),
(11, 'Scripts vanuit een GET request uitvoeren in ninjaOne', 'ik wil in plaats van handmatig lange stukken code ook via een GET request de scripts kunnen uitvoeren binnen bepaalde netwerk-pools. Dit zodat ik sneller kan schakelen en handelen bijvoorbeeld bij een uitrol of aanpassing in software ondersteuning', NULL, 1, 'in_overweging', '2026-07-06 07:37:56', '2026-07-07 08:53:07', NULL, 'Algemeen'),
(12, 'Lijst met minix in NinjaOne', 'Momenteel heb ik geen overzicht of de minix een NinjaOne installatie hebben\r\nEen lijst maken met alle device namen op het netwerk', NULL, 1, 'goedgekeurd', '2026-07-06 10:05:00', '2026-07-07 08:53:15', NULL, 'Algemeen'),
(13, 'Tickets een escalatie nummer + instantie kunnen toekennen', 'Bijvoorbeeld voor een ticket waar je ACA of clearsolutions bij nodig hebt\r\nCAS-109311-L4Z5L7 - Nieuw - Tijdzone aanpassen in nieuwe policy ACA:000133869', 9, 1, 'uitgevoerd', '2026-07-06 10:18:10', '2026-07-07 08:51:22', NULL, 'Algemeen'),
(14, 'Telefoonlijst omzetten naar import/export', 'De telefoonlijst wordt nu in Excel gemaakt, dit omzetten naar een vcf bestand', 19, 1, 'uitgevoerd', '2026-07-06 14:26:15', '2026-07-07 08:51:14', NULL, 'Algemeen'),
(15, 'ASML labels ACCESS database', 'Er is een access databse waarbij niemand weet of en hoe het bestaat maar wel cruciaal is voor de ASML labels', 13, 1, 'nieuw', '2026-07-07 07:16:11', '2026-07-07 07:16:11', NULL, 'Algemeen'),
(16, 'Wachtwoord delen', 'Een linkje waarin je wachtwoorden kan aanmaken, die je 1 keer kan delen \r\n\r\nLink blijft actief om te traceren hoe vaak iemand zijn unieke link opent\r\nMaar wachtwoord wordt maar 1x decrypted\r\n\r\nVoor nu 2 emails versturen voor wachtwoord & username los', NULL, 1, 'in_overweging', '2026-07-08 07:47:18', '2026-07-09 07:51:21', NULL, 'Algemeen'),
(17, 'Password manager', 'Er is niets gefaciliteerd voor password management\r\n- Microsoft\r\n- opensource\r\n- Zakelijk te gebruiken\r\n- proton pass?', NULL, 1, 'nieuw', '2026-07-09 09:14:42', '2026-07-09 09:14:42', NULL, 'Algemeen'),
(18, 'API uitbreiden en werkend krijgen met C# (3 laags solid)', 'API uitbreiden en werkend krijgen met C# (3 laags solid)', NULL, 1, 'goedgekeurd', '2026-07-09 12:17:22', '2026-07-21 07:43:11', NULL, 'Algemeen'),
(19, 'Update intranet', 'Een aantal kleine verbeterpunten:\r\n\r\nLogging:\r\n- Verdachte login pogingen mailen\r\n- Filteren op niet ingelogd naast de users\r\n- Post data in popup weergeven in plaats van veel plek op neemt\r\n- logging ouder dan X dagen verwijderen\r\n\r\nUitgifte:\r\n- Toestemming manager vinkje\r\n\r\nCRM\r\n- Hirarchie keyusers/ stamboom VHE\r\n- Nieuwe extentie \"urenstaat\" bij CRM\r\nTijd schrijven hoe laat, op welke locatie (locaties toevoegen via aparte extensie wat persoongebonden of algemeen zijn, zodat als ik een klant of locatie toevoeg niet iedereen of selectief aantal, of hele bedrijf ziet, zoals \"kantoor\" iedereen en thuis alleen ik, maar klant raith bijvoorbeeld 3 mensen dit zien\r\nOnderstaand powershell commando werkt\r\n\r\n$headers = @{\r\n    \"x-anwb-caller-id\" = \"routing/traffic-info-web\"\r\n}\r\n\r\n$response = Invoke-RestMethod -Uri \"https://api.anwb.nl/routing/route/v1/route/car?locations=51.193943%2C6.001977%3A51.454764%2C5.389512&tollInfo=true&traffic=true&routeType=fastest&includeAlternatives=true\" -Headers $headers\r\n\r\n$response.value | ForEach-Object {\r\n    [PSCustomObject]@{\r\n        RouteId     = $_.id\r\n        AfstandKm   = [math]::Round($_.summary.distanceInMeters / 1000, 1)\r\n        DuurMinuten = [math]::Round($_.summary.durationInSeconds / 60, 0)\r\n        Wegen       = $_.summary.roadNumbers -join \", \"\r\n        Tol         = $_.summary.tollRoads\r\n    }\r\n} | Format-Table -AutoSize\r\n\r\n\r\nAlleen zelf coordinaten ophalen op basis van een adres een api voor vinden\r\nVoor nu handmatig invullen naast adres\r\n\r\nTicket\r\n- Omschrijving uitklapbaar maken in plaats van dat je alles ziet\r\n- Markeren als Cyber risico om hem aan de grafiek te kunnen toevoegen\r\n- Tijd logging (5min, 10min, 15min, 30min, 45 min, 60min)\r\n- Bij opmerking titel mee kunnen geven\r\n- Een caterogie aanpassen, of zoekend selecteren. \r\nDus als ik bij de kennisbank hetzelfde kan doen zou top zijn, als ik 2 seconden niet getypt heb met AJAX ophalen\r\n\r\nSchijfgebruik \r\n- Device kunnen koppelen aan medewerker\r\n\r\n\r\nAgenda\r\n - inplannen taak allen in behandeling taken zien of kunnen filteren op een goede manier. Geen overzicht welke afspraak waarvoor is.\r\n\r\nTools\r\n - vanuit apparaat status waar herstarten bij staat, user opzoeken en een grote mail export voor maken \r\nHet idee is dat we vanuit de CSV een import doen naar mijn systeem, zodat ik niet elke maandag handmatig X gebruikers moet vragen om hun apparaat te herstarten\r\nDit mailtje wil ik dynamisch hebben staan waarin ik in het portaal kan configureren of de gebruikers als CC of BCC staan, wat het berichtinhoud is ect\r\n\r\nVerbeterpunten & tickets gelijk trekken qua functionaliteit', NULL, 1, 'uitgevoerd', '2026-07-14 06:51:41', '2026-07-21 07:43:35', NULL, 'Algemeen'),
(20, 'Project verwerken linssen yachts', 'BHV app gemaakt voor een boten bedrijf. Dit uitwerken onder BHV', NULL, 1, 'nieuw', '2026-07-14 09:07:55', '2026-07-14 09:07:55', NULL, 'Algemeen'),
(21, 'Besprekingen Frank', 'Mark mailtjes gestuurd over iets (20-07-2026) rond 08:10\r\nMaandag 20-07-2026 over Exact\r\nWoensdag 23-07-2026 over laptop medewerker', NULL, 1, 'nieuw', '2026-07-20 06:24:03', '2026-07-20 06:24:03', NULL, 'Algemeen'),
(22, 'Verbeterpunten Portaal', '- Ticket\r\nOpmerking titel wel verplicht omschrijving niet.', NULL, 1, 'nieuw', '2026-07-21 07:46:27', '2026-07-21 07:46:27', NULL, 'Algemeen'),
(23, 'Labelen script', 'Een printer shell script maken', NULL, 1, 'nieuw', '2026-07-21 14:27:01', '2026-07-21 14:27:01', NULL, 'Algemeen'),
(24, 'klant bestand updaten', 'In Zerox alle vendors\r\nAlle ASML \r\nadressen updaten', NULL, 1, 'nieuw', '2026-07-21 14:27:27', '2026-07-21 14:27:27', NULL, 'Algemeen'),
(25, 'Josephine lijstje verbetering / aanschaf', 'Lijst maken met > materialen \r\nDit moet\r\nPlek/ afdeling\r\nWie heeft er baat bij\r\nWat is dan nodig > type laptop, licentie code van welke uitgever ect\r\n\r\nProcessen verbeteren\r\nOnderzoeken waar mensen tegen aan lopen wat anders moet\r\n\r\nOverig\r\nAndere zaken wat openstaat voor verandering', 1, 1, 'in_overweging', '2026-07-23 12:51:40', '2026-07-23 13:01:27', NULL, 'Upgrades');
